INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('bench', 'پرس سینه هالتر', 'Barbell Bench Press', 'chest', 0, 'barbell', 'حرکت اصلی امروز. کتف‌ها جمع و پایین. هالتر را در ۲ تا ۳ ثانیه تا روی سینه بیاور، مکث کوتاه، بعد فشار بده.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('incline_db', 'پرس بالا سینه دمبل', 'Incline Dumbbell Press', 'chest', 0, 'dumbbell', 'زاویه‌ی نیمکت ۳۰ تا ۴۵ درجه. دمبل‌ها را تا کشش کامل سینه پایین بیاور.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('rdl', 'ددلیفت رومانیایی', 'Romanian Deadlift', 'hamstrings_glutes', 1, 'barbell', 'زانو کمی خم. لگن را به عقب بفرست تا کشش پشت ران را حس کنی. هالتر نزدیک پا.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('cable_row', 'زیربغل کابل نشسته', 'Seated Cable Row', 'back', 0, 'cable', 'کمر صاف. دستگیره را به شکم بکش و کتف‌ها را به هم نزدیک کن.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('lateral', 'نشر جانب', 'Dumbbell Lateral Raise', 'shoulders', 0, 'dumbbell', 'دمبل‌ها را تا ارتفاع شانه بالا بیاور، بدون تاب دادن بدن.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('facepull', 'فیس‌پول', 'Face Pull', 'rear_delts', 0, 'cable', 'طناب را به سمت صورت بکش و دست‌ها را از هم باز کن. آرنج‌ها بالا.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('squat', 'اسکوات هالتر', 'Barbell Back Squat', 'quads', 1, 'barbell', 'حرکت اصلی امروز. پاها کمی بازتر از شانه. تا موازی شدن ران با زمین پایین برو، زانو هم‌جهت پنجه.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('leg_press', 'پرس پا', 'Leg Press', 'quads', 1, 'machine', 'کمر و لگن به پشتی چسبیده. تا جایی پایین بیاور که لگن از پشتی جدا نشود، زانو قفل نشود.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('incline_bb', 'پرس بالا سینه هالتر', 'Incline Barbell Bench Press', 'chest', 0, 'barbell', 'زاویه‌ی ۳۰ درجه. هالتر را تا بالای سینه بیاور، کتف‌ها جمع.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('pulldown', 'لت‌پول‌داون', 'Lat Pulldown', 'back', 0, 'cable', 'سینه بالا، میله را تا بالای سینه بکش. آرنج‌ها به سمت پایین و پهلو.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('calf_stand', 'ساق پا ایستاده', 'Standing Calf Raise', 'calves', 1, 'machine', 'پاشنه را کامل پایین بیاور و بالا یک ثانیه مکث کن.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('plank', 'پلانک', 'Plank', 'core', 0, 'bodyweight', 'بدن در یک خط صاف. شکم و باسن سفت، لگن نیفتد.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('cs_row', 'زیربغل دمبل روی نیمکت شیب‌دار', 'Chest-Supported Dumbbell Row', 'back', 0, 'dumbbell', 'حرکت اصلی امروز. سینه روی نیمکت ۳۰ تا ۴۵ درجه. دمبل‌ها را به سمت لگن بکش و کتف‌ها را جمع کن؛ کمر استراحت می‌کند.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('pullup', 'بارفیکس', 'Pull-Up / Assisted Pull-Up', 'back', 0, 'bodyweight', 'از آویزان کامل شروع کن و چانه را بالای میله ببر. با دستگاه کمکی، وزن کمکی را منفی بنویس (مثلاً ‎-40‎).') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('bulgarian', 'اسکوات بلغاری', 'Bulgarian Split Squat', 'quads', 1, 'dumbbell', 'پای عقب روی نیمکت. مستقیم پایین برو تا ران جلو موازی زمین شود.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('fly', 'قفسه‌ی کابل', 'Cable Chest Fly', 'chest', 0, 'cable', 'آرنج کمی خم و ثابت. در ست آخر چند تکرار نیمه در حالت کشیده (Partials) بزن.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('curl', 'جلو بازو دمبل', 'Dumbbell Biceps Curl', 'biceps', 0, 'dumbbell', 'آرنج کنار بدن و ثابت. آرام پایین بیاور.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('oh_tri', 'پشت بازو کابل از بالای سر', 'Overhead Cable Triceps Extension', 'triceps', 0, 'cable', 'آرنج‌ها کنار سر و ثابت. فقط ساعد حرکت کند و پایین کشش کامل بگیر.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('deadlift', 'ددلیفت', 'Conventional Deadlift', 'hamstrings_glutes', 1, 'barbell', 'حرکت اصلی امروز. هالتر روی وسط پا. کمر صاف، سینه بالا. با فشار پاها بلند شو، نه با کشیدن کمر.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('ohp', 'پرس سرشانه ایستاده', 'Standing Overhead Press', 'shoulders', 0, 'barbell', 'باسن و شکم سفت، کمر قوس زیاد نگیرد. هالتر در خط صاف بالای سر برود.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('leg_curl', 'پشت ران دستگاه', 'Lying Leg Curl', 'hamstrings_glutes', 1, 'machine', 'لگن روی نیمکت بماند. آرام پایین بیاور.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('knee_raise', 'بالا آوردن زانو آویزان', 'Hanging Knee Raise', 'core', 0, 'bodyweight', 'بدون تاب. زانوها را تا سینه بالا بیاور و آرام پایین بیاور.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('calf_seated', 'ساق پا نشسته', 'Seated Calf Raise', 'calves', 1, 'machine', 'دامنه‌ی کامل و مکث در بالا.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('row', 'زیربغل هالتر خم', 'Barbell Bent-Over Row', 'back', 0, 'barbell', 'کمر صاف، لگن به عقب. هالتر را به سمت ناف بکش، بدون تاب دادن بدن.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('lunge', 'لانج با دمبل', 'Walking Lunge', 'quads', 1, 'dumbbell', 'بالاتنه صاف. زانوی عقب نزدیک زمین، زانوی جلو بالای مچ پا.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('dips', 'دیپ سینه', 'Chest Dips', 'chest', 0, 'bodyweight', 'بدن رو به جلو تا فشار روی سینه بیاید. درد شانه = جایگزین با پرس سینه دمبل. در ست آخر Partials.') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
INSERT INTO exercises (id, name_fa, name_en, muscle_primary, is_lower, equipment, cue_fa) VALUES ('rope_pushdown', 'پشت بازو طناب', 'Triceps Rope Pushdown', 'triceps', 0, 'cable', '') ON CONFLICT (id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, muscle_primary = excluded.muscle_primary, is_lower = excluded.is_lower, equipment = excluded.equipment, cue_fa = excluded.cue_fa;
